xinshengCustomCss:
/* 0. 彻底重置 */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; padding: 0 !important; background: transparent !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important; }
.xt-root::-webkit-scrollbar, .xt-text::-webkit-scrollbar { width: 0 !important; display: none !important; }

/* ================= 1. 根容器 (支持上下滑动 + iOS毛玻璃质感) ================= */
.xt-root {
    width: 360px !important; height: 650px !important;
    background: rgba(252, 252, 252, 0.9) !important; /* 半透明底色 */
    backdrop-filter: blur(35px) saturate(180%) !important; /* 核心毛玻璃模糊与饱和度 */
    -webkit-backdrop-filter: blur(25px) saturate(180%) !important;
    border: 1px solid rgba(255, 255, 255, 0.4) !important; /* 边缘高光增强玻璃感 */
    border-radius: 20px !important; 
    position: relative !important; margin: 20px auto !important;
    overflow-y: auto !important; overflow-x: hidden !important; pointer-events: auto !important;
}

/* ================= 2. 顶部区域 ================= */
/* 2. 缩略图 */
.xt-text:nth-of-type(2) {
    position: absolute !important; top: 22px !important; left: 15px !important; width: 50px !important; height: 50px !important;
    background: url('https://i.postimg.cc/NMJR4Cqf/IMG-0496.jpg') center/cover no-repeat !important;
    border-radius: 6px !important; z-index: 10 !important;
}
/* 3. 标题 */
.xt-text:nth-of-type(3) {
    position: absolute !important; top: 18px !important; left: 75px !important;
    font-size: 16px !important; font-weight: 600 !important; color: #000 !important; z-index: 10 !important;
}
/* 4. 选项按钮 */
.xt-text:nth-of-type(4) {
    position: absolute !important; top: 42px !important; left: 75px !important;
    font-size: 13px !important; color: #333 !important; background: rgba(255,255,255,0.8) !important;
    padding: 4px 10px !important; border-radius: 12px !important; border: 1px solid rgba(229,229,234,0.8) !important;
    z-index: 10 !important;
}
/* 5. 关闭按钮 (使用图片URL) */
.xt-text:nth-of-type(5) {
    position: absolute !important; top: 15px !important; right: 15px !important; width: 30px !important; height: 30px !important;
    background: url('https://i.postimg.cc/hP30xtJT/IMG-3940.png') center/cover no-repeat !important; 
    border-radius: 50% !important; z-index: 10 !important; color: transparent !important;
}

/* ================= 3. 中间大空白文字区 ================= */
/* 6. 白底背景 */
